import{_ as a,C as s,c as i,o as r,a3 as e,G as n}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Send and confirm a quotation","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/sales/quotations-orders/send-and-confirm-quotation.md","filePath":"master/sales/sales/quotations-orders/send-and-confirm-quotation.md","lastUpdated":1793074831000}'),l={name:"master/sales/sales/quotations-orders/send-and-confirm-quotation.md"};function h(d,t,u,c,g,m){const o=s("ImagePopup");return r(),i("div",null,[t[0]||(t[0]=e('<h1 id="send-and-confirm-a-quotation" tabindex="-1">Send and confirm a quotation <a class="header-anchor" href="#send-and-confirm-a-quotation" aria-label="Permalink to &quot;Send and confirm a quotation&quot;">​</a></h1><p>A quotation is an offer. Once the lines and prices are right, you send it to the customer. When the customer says yes, you confirm it. The quotation then becomes a sales order, and the work of delivering and invoicing can start.</p><p>This page walks through the whole path, one button at a time. For each button you will see what it is for, when to use it and what happens next.</p><blockquote><p><strong>In simple words:</strong> Send the offer, wait for a yes, then click <strong>Confirm</strong>. The offer becomes an order.</p></blockquote><h2 id="an-example-used-on-this-page" tabindex="-1">An example used on this page <a class="header-anchor" href="#an-example-used-on-this-page" aria-label="Permalink to &quot;An example used on this page&quot;">​</a></h2><p>Azure Interiors asks for a price on two products. You create quotation <strong>SO/1</strong> with these lines:</p><table tabindex="0"><thead><tr><th>Product</th><th>Quantity</th><th>Unit price</th><th>Tax</th></tr></thead><tbody><tr><td>Camping Hammock</td><td>5</td><td>$65.00</td><td>15 %</td></tr><tr><td>Smart LED Desk Lamp</td><td>10</td><td>$20.00</td><td>15 %</td></tr></tbody></table><p>The untaxed amount is $525.00. The tax is $78.75. The total is <strong>$603.75</strong>.</p><p>To create a quotation like this, see <a href="./create-quotation.html">Create a quotation</a>.</p><h2 id="find-your-quotation" tabindex="-1">Find your quotation <a class="header-anchor" href="#find-your-quotation" aria-label="Permalink to &quot;Find your quotation&quot;">​</a></h2><ol><li>Go to <code>Sales → Orders → Quotations</code>.</li><li>Click the quotation to open it.</li></ol><p>The page has four tabs: <strong>View</strong>, <strong>Edit</strong>, <strong>Invoices</strong> and <strong>Deliveries</strong>. The <strong>Deliveries</strong> tab only shows when the Inventories plugin is installed. Use <strong>View</strong> to read the quotation. Use <strong>Edit</strong> to change it.</p><h2 id="the-state-bar" tabindex="-1">The state bar <a class="header-anchor" href="#the-state-bar" aria-label="Permalink to &quot;The state bar&quot;">​</a></h2><p>The <strong>State</strong> bar shows where the quotation is in its life:</p><ul><li><strong><em>Quotation:</em></strong> The draft you are preparing. Nobody has been told yet.</li><li><strong><em>Quotation Sent:</em></strong> You emailed the quotation to the customer.</li><li><strong><em>Sales Order:</em></strong> The quotation is confirmed.</li></ul><p>A quotation can also be <strong>Cancelled</strong>. You see this status in the list.</p><p>You do not move the bar by hand. It changes when you click a button. Sending moves <strong>Quotation</strong> to <strong>Quotation Sent</strong>. <strong>Confirm</strong> moves it to <strong>Sales Order</strong>.</p>',17)),n(o,{src:"/images1/sales/quotation_view.png",alt:"Quotation page with the Cancel, Confirm, Preview, Send By Email and Delete buttons and the state bar"}),t[1]||(t[1]=e('<h2 id="the-buttons-at-the-top" tabindex="-1">The buttons at the top <a class="header-anchor" href="#the-buttons-at-the-top" aria-label="Permalink to &quot;The buttons at the top&quot;">​</a></h2><p>A quotation in <strong>Quotation</strong> or <strong>Quotation Sent</strong> state shows these buttons:</p><ul><li><strong><em>Cancel:</em></strong> Stops the quotation. You can email the customer at the same time.</li><li><strong><em>Confirm:</em></strong> Turns the quotation into a sales order.</li><li><strong><em>Preview:</em></strong> Shows the quotation the way the customer sees it.</li><li><strong><em>Send By Email:</em></strong> Emails the quotation to the customer.</li><li><strong><em>Delete:</em></strong> Removes the quotation.</li></ul><p>Some buttons hide when they no longer make sense:</p><ul><li><strong>Confirm</strong> and <strong>Send By Email</strong> hide once the quotation is a sales order or is cancelled.</li><li><strong>Delete</strong> hides once the quotation is a sales order.</li><li><strong>Set as Quotation</strong> only shows on a cancelled quotation.</li></ul><h2 id="check-the-quotation-with-preview" tabindex="-1">Check the quotation with Preview <a class="header-anchor" href="#check-the-quotation-with-preview" aria-label="Permalink to &quot;Check the quotation with Preview&quot;">​</a></h2><p>Click <strong>Preview</strong> before you send anything. A window opens with the quotation as a document. You see the same layout the customer gets.</p><p>Check the customer name, the lines, the taxes and the total. For SO/1, the total must read $603.75.</p><p>Close the window when you are done. Preview changes nothing on the quotation.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If something looks wrong, close the window, open the <strong>Edit</strong> tab and fix it. Then preview again.</p></div><h2 id="send-the-quotation-by-email" tabindex="-1">Send the quotation by email <a class="header-anchor" href="#send-the-quotation-by-email" aria-label="Permalink to &quot;Send the quotation by email&quot;">​</a></h2><p>Use <strong>Send By Email</strong> to give the customer the offer. This is the normal next step after Preview.</p><ol><li>Click <strong>Send By Email</strong>. The <strong>Send Quotation By Email</strong> window opens.</li><li>Check <strong>Partners</strong>. The customer is already selected. You can add more people, for example a colleague of the customer.</li><li>Read the <strong>Subject</strong>. It is filled in for you, and it names the customer and the quotation number.</li><li>Read the <strong>Description</strong>. This is the message body. It greets the customer, names the quotation and shows the total. Edit it if you want to add a personal line.</li><li>Check the <strong>Attachment</strong>. Aureus has already made a PDF of the quotation and attached it. Click <strong>Remove</strong> if you do not want to send it.</li><li>Click <strong>Submit</strong> to send. Click <strong>Cancel</strong> to close the window without sending.</li></ol>',13)),n(o,{src:"/images1/sales/send_by_email_window.png",alt:"Send Quotation By Email window with Partners, Subject, Description and the PDF attachment"}),t[2]||(t[2]=e('<h3 id="what-happens-after-you-click-submit" tabindex="-1">What happens after you click Submit <a class="header-anchor" href="#what-happens-after-you-click-submit" aria-label="Permalink to &quot;What happens after you click Submit&quot;">​</a></h3><ul><li>Each selected partner gets the email with the PDF.</li><li>Aureus shows a message that says who received it.</li><li>The state changes from <strong>Quotation</strong> to <strong>Quotation Sent</strong>. This only happens if at least one email went out.</li></ul><p>If some emails fail, Aureus tells you which ones and why. The quotation still moves to <strong>Quotation Sent</strong> when at least one email was sent.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A partner needs an email address. If no selected partner has one, Aureus shows a warning and sends nothing. The state does not change.</p></div><p>You can send the quotation again at any time while it is still a quotation. This is useful when you changed the lines after the first email.</p><h2 id="confirm-the-quotation" tabindex="-1">Confirm the quotation <a class="header-anchor" href="#confirm-the-quotation" aria-label="Permalink to &quot;Confirm the quotation&quot;">​</a></h2><p>Click <strong>Confirm</strong> when the customer accepts. You can also confirm straight from <strong>Quotation</strong>, without sending first. This is handy when the customer agreed by phone.</p><ol><li>Open the quotation.</li><li>Click <strong>Confirm</strong>.</li><li>Aureus opens the order and shows a success message.</li></ol><p>The state bar now reads <strong>Sales Order</strong>. In our example, SO/1 is now a real order for Azure Interiors.</p><h3 id="what-confirm-sets-in-motion" tabindex="-1">What Confirm sets in motion <a class="header-anchor" href="#what-confirm-sets-in-motion" aria-label="Permalink to &quot;What Confirm sets in motion&quot;">​</a></h3><ul><li>The <strong>Invoice Status</strong> becomes <strong>To Invoice</strong>. You can now create an invoice.</li><li>If the Inventories plugin is installed, Aureus asks stock to prepare the delivery. You then follow it in the <strong>Deliveries</strong> tab.</li><li>If <strong>Lock Confirm Sales</strong> is on in the settings, the order is locked at once. See <a href="./manage-orders.html#lock-an-order">Lock an order</a>.</li></ul><p>If something stops the confirmation, Aureus shows an error message and the quotation stays as it was.</p><p>Read <a href="./manage-orders.html">Manage orders</a> for what to do next.</p><h2 id="cancel-a-quotation" tabindex="-1">Cancel a quotation <a class="header-anchor" href="#cancel-a-quotation" aria-label="Permalink to &quot;Cancel a quotation&quot;">​</a></h2><p>Cancel when the customer says no, or when the offer is no longer valid.</p><ol><li><p>Click <strong>Cancel</strong>. The <strong>Cancel Quotation</strong> window opens and asks: &quot;Are you sure you want to cancel this Quotation?&quot;</p></li><li><p>Check <strong>Partner</strong>, <strong>Subject</strong> and <strong>Description</strong>. They hold a ready message that tells the customer the order is cancelled.</p></li><li><p>Choose one button:</p><ul><li><strong><em>Send &amp; Cancel:</em></strong> Cancels the quotation and emails the customer.</li><li><strong><em>Cancel:</em></strong> Cancels the quotation and sends no email.</li><li><strong><em>Close:</em></strong> Closes the window. The quotation stays as it was.</li></ul></li></ol><p>The status becomes <strong>Cancelled</strong>. Cancel also shows on a confirmed order. See <a href="./manage-orders.html">Manage orders</a>.</p>',17)),n(o,{src:"/images1/sales/cancel_quotation_window.png",alt:"Cancel Quotation window with Send & Cancel, Cancel and Close buttons"}),t[3]||(t[3]=e('<h2 id="reopen-a-cancelled-quotation" tabindex="-1">Reopen a cancelled quotation <a class="header-anchor" href="#reopen-a-cancelled-quotation" aria-label="Permalink to &quot;Reopen a cancelled quotation&quot;">​</a></h2><p>Changed your mind, or did the customer come back? Open the cancelled quotation and click <strong>Set as Quotation</strong>. The state goes back to <strong>Quotation</strong>. You can then edit, send and confirm it again.</p><h2 id="delete-a-quotation" tabindex="-1">Delete a quotation <a class="header-anchor" href="#delete-a-quotation" aria-label="Permalink to &quot;Delete a quotation&quot;">​</a></h2><p><strong>Delete</strong> removes the quotation from the list. The Orders list keeps deleted records in the <strong>Archived</strong> view.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Use <strong>Cancel</strong>, not <strong>Delete</strong>, when you want to keep a record of the offer. A cancelled quotation stays in the list. A confirmed order cannot be deleted.</p></div><h2 id="quick-reference" tabindex="-1">Quick reference <a class="header-anchor" href="#quick-reference" aria-label="Permalink to &quot;Quick reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You want to</th><th>Click</th><th>State afterwards</th></tr></thead><tbody><tr><td>See what the customer sees</td><td><strong>Preview</strong></td><td>No change</td></tr><tr><td>Email the offer</td><td><strong>Send By Email</strong>, then <strong>Submit</strong></td><td><strong>Quotation Sent</strong></td></tr><tr><td>Accept the offer</td><td><strong>Confirm</strong></td><td><strong>Sales Order</strong></td></tr><tr><td>Drop the offer</td><td><strong>Cancel</strong></td><td><strong>Cancelled</strong></td></tr><tr><td>Reopen a cancelled offer</td><td><strong>Set as Quotation</strong></td><td><strong>Quotation</strong></td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./create-quotation.html">Create a quotation</a></li><li><a href="./manage-orders.html">Manage orders</a></li><li><a href="./../configuration/settings.html">Settings</a></li><li><a href="./../../../getting-started/chatter.html">Chatter</a></li></ul>',9))])}const q=a(l,[["render",h]]);export{f as __pageData,q as default};
